-- P0 TP-08: when an owner's project is made private or trashed, previously
-- published immutable portfolio HTML might still mention that project.
-- There is no verified cross-release dependency index yet. Conservative
-- invalidation blocks ALL that owner's live/pending portfolio routes.
-- Host/CDN direct asset revocation is a separate proof gate, NOT claimed here.
-- Do not assume the autogenerated constraint name; enforce using a named rule.
do $body$
declare v_constraint text;
begin
  select conname into v_constraint from pg_constraint
    where conrelid='public.private_release_visibility_events'::regclass
      and contype='c' and pg_get_constraintdef(oid) like '%event_type%';
  if v_constraint is null then
    raise exception 'Missing release event type constraint';
  end if;
  execute format('alter table public.private_release_visibility_events drop constraint %I',v_constraint);
end $body$;
alter table public.private_release_visibility_events
  add constraint kd_private_release_event_kind
  check (event_type in ('PREPARE','OWNER_BLOCK','TRASH_BLOCK','OPERATOR_BLOCK',
    'OPERATOR_HOLD_LIFT','PROJECT_PRIVACY_BLOCK'));

create function kadmeion_private.block_owner_portfolios_for_project_privacy()
returns trigger language plpgsql security definer set search_path=''
as $function$
declare
  v_owner uuid;
  v_should_block boolean:=false;
  v_pointer record;
begin
  if tg_table_name='project_exposure_intents' then
    if tg_op<>'UPDATE' then return null; end if;
    v_owner:=old.owner_user_id;
    v_should_block:=
      (old.show_on_profile and not new.show_on_profile)
      or (old.show_case_study and not new.show_case_study);
  elsif tg_table_name='projects' then
    v_owner:=old.owner_user_id;
    v_should_block:=old.trashed_at is null and new.trashed_at is not null;
  else
    raise exception 'Unexpected project privacy trigger';
  end if;
  if not v_should_block then return null; end if;

  -- A transaction that cannot record the complete denial MUST roll back
  -- its privacy change rather than acknowledge an unverified unpublication.
  -- For every existing candidate/live pointer, one update both invalidates
  -- the route and advances the revocation generation.
  for v_pointer in
    update public.private_release_visibility_pointers p
       set status='BLOCKED',candidate_request_id=null,
           candidate_manifest_sha256=null,generation=p.generation+1,
           revocation_generation=p.generation+1,
           updated_at=transaction_timestamp()
      where p.owner_user_id=v_owner and p.status<>'BLOCKED'
        and p.generation<9223372036854775806
      returning p.portfolio_id,p.owner_user_id,p.generation
  loop
    insert into public.private_release_visibility_events(
      portfolio_id,owner_user_id,actor_user_id,operation_id,event_type,
      expected_generation,resulting_generation)
    values(v_pointer.portfolio_id,v_pointer.owner_user_id,(select auth.uid()),
      gen_random_uuid(),'PROJECT_PRIVACY_BLOCK',
      v_pointer.generation-1,v_pointer.generation);
  end loop;

  if exists(
    select 1 from public.private_release_visibility_pointers p
      where p.owner_user_id=v_owner and p.status<>'BLOCKED'
  ) then
    raise exception using errcode='54000',
      message='PROJECT_PRIVACY_RELEASE_REVOCATION_UNAVAILABLE';
  end if;
  return null;
end;
$function$;
revoke all on function kadmeion_private.block_owner_portfolios_for_project_privacy()
  from public,anon,authenticated,service_role;
create trigger kd_owner_project_privacy_release_block
  after update of show_on_profile,show_case_study on public.project_exposure_intents
  for each row execute function kadmeion_private.block_owner_portfolios_for_project_privacy();
create trigger kd_owner_project_trash_release_block
  after update of trashed_at on public.projects
  for each row execute function kadmeion_private.block_owner_portfolios_for_project_privacy();
comment on function kadmeion_private.block_owner_portfolios_for_project_privacy() is
  'Fail-closed owner-wide DB revocation on project privacy withdrawal/Trash. Never claims public CDN cache or direct asset purge.';
